-- ============================================================================
-- GARMIN TRAINING HUB — MIGRAÇÃO 139: Ficha estruturada para "Perfis de
-- corrida" (módulo Perfis de Cliente, lição "Perfis de corrida")
-- ============================================================================
-- Pedido do usuário (2026-09-15): os 3 itens do accordion "Perfis de
-- corrida" (Corredor Iniciante / Dedicado / Atleta de Performance) eram uma
-- lista corrida de <p><strong>Rótulo:</strong></p><ul>...</ul> repetidos —
-- difícil de escanear, sem hierarquia, sem apoio visual.
--
-- Não é um bloco novo no schema: continua `accordion` (items: [{title,
-- html}]), só o HTML de cada item passa a usar classes novas (.cb-profile*,
-- ver contentBlocks.css) — mesmo padrão já usado em .cb-topic-divider/
-- .cb-field/.cb-model-heading (presentação estruturada hand-authored dentro
-- do html, sem precisar de bloco novo).
--
-- Estrutura por perfil: "Quem é" em destaque no topo, 3 seções lado a lado
-- (Como identificar / O que você pode ouvir / O que perguntar, cada uma com
-- ícone svg — mesmo conjunto de icons.js, sem emoji, decisão já tomada
-- nesta trilha em sql/127), "Como conduzir" e as "Linhas para conhecer"
-- como tags (reaproveita o componente .tag já existente, cards.css).
--
-- Nenhum fato do conteúdo muda — só a apresentação.
-- ============================================================================

update lessons
set body = jsonb_set(
  body,
  '{blocks,1,items}',
  $items$
[
  {
    "title": "Corredor Iniciante",
    "html": "<div class=\"cb-profile\"><p class=\"cb-profile-quem\"><strong>Quem é:</strong> Está começando a correr ou retornando ao esporte. Normalmente procura uma experiência simples e quer entender o básico antes de entrar em recursos mais avançados.</p><div class=\"cb-profile-grid\"><div class=\"cb-profile-section\"><div class=\"cb-profile-section-head\"><span class=\"cb-profile-section-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"M19.5 19.5l-4.3-4.3\"/></svg></span><span>Como identificar</span></div><ul class=\"cb-profile-list\"><li>Nunca utilizou relógio GPS</li><li>Está começando ou voltando a correr</li><li>Prioriza simplicidade</li><li>Quer acompanhar tempo, distância e evolução</li><li>Ainda não demonstra necessidade de recursos avançados</li></ul></div><div class=\"cb-profile-section\"><div class=\"cb-profile-section-head\"><span class=\"cb-profile-section-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 3.5c-4.7 0-8.5 3.1-8.5 7 0 2.4 1.5 4.5 3.8 5.8L6 20l4-2c0.6 0.1 1.3 0.2 2 0.2 4.7 0 8.5-3.1 8.5-7s-3.8-7-8.5-7z\"/></svg></span><span>O que você pode ouvir</span></div><div class=\"cb-profile-quotes\"><p class=\"cb-profile-quote\">\"Estou começando a correr.\"</p><p class=\"cb-profile-quote\">\"Quero um relógio para marcar distância.\"</p><p class=\"cb-profile-quote\">\"Nunca usei Garmin.\"</p><p class=\"cb-profile-quote\">\"Qual é o modelo mais simples?\"</p></div></div><div class=\"cb-profile-section\"><div class=\"cb-profile-section-head\"><span class=\"cb-profile-section-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"8.5\"/><path d=\"M9.3 9.6a2.8 2.8 0 0 1 5.4.9c0 1.7-2.2 2.2-2.6 3.7\"/><path d=\"M12 17.2h.01\" stroke-width=\"2.6\"/></svg></span><span>O que perguntar</span></div><div class=\"cb-profile-quotes cb-profile-quotes-ask\"><p class=\"cb-profile-quote\">\"Você já utilizou algum relógio GPS antes?\"</p><p class=\"cb-profile-quote\">\"Quantas vezes por semana você pretende correr?\"</p><p class=\"cb-profile-quote\">\"O que você gostaria de acompanhar nos seus treinos?\"</p></div></div></div><p class=\"cb-profile-conduzir\"><strong>Como conduzir:</strong> Comece pelo objetivo do cliente e explique como a Garmin pode acompanhá-lo desde os primeiros treinos.</p><div class=\"cb-profile-tags\"><span class=\"cb-profile-tags-label\">Linhas para conhecer</span><span class=\"tag\">Forerunner 165</span><span class=\"tag\">Forerunner 70</span><span class=\"tag\">Forerunner 170</span></div></div>"
  },
  {
    "title": "Corredor Dedicado",
    "html": "<div class=\"cb-profile\"><p class=\"cb-profile-quem\"><strong>Quem é:</strong> Já incorporou a corrida à rotina e começa a buscar mais informações para entender desempenho, evolução e treinamento.</p><div class=\"cb-profile-grid\"><div class=\"cb-profile-section\"><div class=\"cb-profile-section-head\"><span class=\"cb-profile-section-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"M19.5 19.5l-4.3-4.3\"/></svg></span><span>Como identificar</span></div><ul class=\"cb-profile-list\"><li>Corre com frequência</li><li>Demonstra familiaridade com métricas</li><li>Fala sobre pace, ritmo ou provas</li><li>Já utiliza algum relógio</li><li>Busca evolução e não apenas registro da atividade</li></ul></div><div class=\"cb-profile-section\"><div class=\"cb-profile-section-head\"><span class=\"cb-profile-section-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 3.5c-4.7 0-8.5 3.1-8.5 7 0 2.4 1.5 4.5 3.8 5.8L6 20l4-2c0.6 0.1 1.3 0.2 2 0.2 4.7 0 8.5-3.1 8.5-7s-3.8-7-8.5-7z\"/></svg></span><span>O que você pode ouvir</span></div><div class=\"cb-profile-quotes\"><p class=\"cb-profile-quote\">\"Corro três ou quatro vezes por semana.\"</p><p class=\"cb-profile-quote\">\"Quero melhorar meu pace.\"</p><p class=\"cb-profile-quote\">\"Estou treinando para uma prova.\"</p><p class=\"cb-profile-quote\">\"Quero GPS multibanda.\"</p><p class=\"cb-profile-quote\">\"Quero acompanhar meu VO2 Max.\"</p></div></div><div class=\"cb-profile-section\"><div class=\"cb-profile-section-head\"><span class=\"cb-profile-section-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"8.5\"/><path d=\"M9.3 9.6a2.8 2.8 0 0 1 5.4.9c0 1.7-2.2 2.2-2.6 3.7\"/><path d=\"M12 17.2h.01\" stroke-width=\"2.6\"/></svg></span><span>O que perguntar</span></div><div class=\"cb-profile-quotes cb-profile-quotes-ask\"><p class=\"cb-profile-quote\">\"Você está treinando para alguma prova?\"</p><p class=\"cb-profile-quote\">\"O que você gostaria de melhorar no seu desempenho?\"</p><p class=\"cb-profile-quote\">\"Você já acompanha suas métricas de treinamento?\"</p><p class=\"cb-profile-quote\">\"O que sente falta no seu relógio atual?\"</p></div></div></div><p class=\"cb-profile-conduzir\"><strong>Como conduzir:</strong> A conversa começa a sair do simples registro do treino e entra em acompanhamento de performance.</p><div class=\"cb-profile-tags\"><span class=\"cb-profile-tags-label\">Linhas para conhecer</span><span class=\"tag\">Forerunner 265</span><span class=\"tag\">Forerunner 570</span><span class=\"tag\">Forerunner 955</span></div></div>"
  },
  {
    "title": "Atleta de Performance",
    "html": "<div class=\"cb-profile\"><p class=\"cb-profile-quem\"><strong>Quem é:</strong> Tem alto volume de treinamento, participa de provas e procura ferramentas mais completas para acompanhar sua preparação.</p><div class=\"cb-profile-grid\"><div class=\"cb-profile-section\"><div class=\"cb-profile-section-head\"><span class=\"cb-profile-section-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"M19.5 19.5l-4.3-4.3\"/></svg></span><span>Como identificar</span></div><ul class=\"cb-profile-list\"><li>Pratica mais de uma modalidade</li><li>Participa de provas</li><li>Já possui experiência com relógios esportivos</li><li>Demonstra conhecimento técnico</li><li>Procura evolução ou upgrade</li><li>Tem necessidades específicas de treinamento</li></ul></div><div class=\"cb-profile-section\"><div class=\"cb-profile-section-head\"><span class=\"cb-profile-section-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M12 3.5c-4.7 0-8.5 3.1-8.5 7 0 2.4 1.5 4.5 3.8 5.8L6 20l4-2c0.6 0.1 1.3 0.2 2 0.2 4.7 0 8.5-3.1 8.5-7s-3.8-7-8.5-7z\"/></svg></span><span>O que você pode ouvir</span></div><div class=\"cb-profile-quotes\"><p class=\"cb-profile-quote\">\"Estou treinando para Ironman.\"</p><p class=\"cb-profile-quote\">\"Faço triathlon.\"</p><p class=\"cb-profile-quote\">\"Treino todos os dias.\"</p><p class=\"cb-profile-quote\">\"Estou buscando um upgrade.\"</p><p class=\"cb-profile-quote\">\"Preciso de mais autonomia.\"</p></div></div><div class=\"cb-profile-section\"><div class=\"cb-profile-section-head\"><span class=\"cb-profile-section-icon\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"8.5\"/><path d=\"M9.3 9.6a2.8 2.8 0 0 1 5.4.9c0 1.7-2.2 2.2-2.6 3.7\"/><path d=\"M12 17.2h.01\" stroke-width=\"2.6\"/></svg></span><span>O que perguntar</span></div><div class=\"cb-profile-quotes cb-profile-quotes-ask\"><p class=\"cb-profile-quote\">\"Qual é sua principal modalidade hoje?\"</p><p class=\"cb-profile-quote\">\"Você está treinando para alguma prova?\"</p><p class=\"cb-profile-quote\">\"O que você sente falta no seu relógio atual?\"</p><p class=\"cb-profile-quote\">\"Qual informação é mais importante para acompanhar seu treinamento?\"</p></div></div></div><p class=\"cb-profile-conduzir\"><strong>Como conduzir:</strong> Aqui, a pergunta deixa de ser apenas \"qual atividade você pratica?\" e passa a ser: \"O que você precisa acompanhar melhor no seu treinamento?\"</p><div class=\"cb-profile-tags\"><span class=\"cb-profile-tags-label\">Linhas para conhecer</span><span class=\"tag\">Forerunner 970</span><span class=\"tag\">Forerunner 965</span><span class=\"tag\">fēnix 8</span></div></div>"
  }
]
$items$::jsonb
)
where id = '745d31e5-6b31-411c-bbe0-c7e5b2ef3919'
  and body->'blocks'->1->>'type' = 'accordion';

